class Resource {
    int* data;
public:
    explicit Resource(size_t s) : data(new int[s]) {}
    ~Resource() { delete[] data; } // 1: Destructor

    // 2: Copy Constructor (Deep Copy)
    Resource(const Resource& other) : data(new int[other.size]) {
        std::copy(other.data, other.data + other.size, data);
    }

    // 3: Copy Assignment (Copy and Swap)
    Resource& operator=(const Resource& other) {
        Resource temp(other);
        std::swap(data, temp.data);
        return *this;
    }

    // 4: Move Constructor
    Resource(Resource&& other) noexcept : data(other.data) {
        other.data = nullptr;
    }

    // 5: Move Assignment
    Resource& operator=(Resource&& other) noexcept {
        delete[] data;
        data = other.data;
        other.data = nullptr;
        return *this;
    }
};

// --- Rule of Zero ---

class RAIIResource {
    std::unique_ptr<int[]> data;
public:
    // No custom definitions needed for Dtor or Move.
    // Copy ops automatically deleted.
    RAIIResource(size_t s) : data(std::make_unique<int[]>(s)) {}
};
